# Living carnivorans: every genus, with its best-known species and the others mentioned.
# Ranges are country-level outlines (with boxes for parts of countries and for seas), so they
# are approximate. IUCN statuses are given only where well established.


def C(*names, **clip):
    return {'countries': list(names), **clip}


def part(country, lon0, lat0, lon1, lat1):
    return {'country': country, 'bbox': [lon0, lat0, lon1, lat1]}


def sea(lon0, lat0, lon1, lat1):
    return {'sea': [lon0, lat0, lon1, lat1]}


